(() => {
  'use strict';
  const C=window.ActiveRecallCore, Store=window.ActiveRecallStorage, Doc=window.ActiveRecallDocumentImport;
  let db, page='home', focusedCourse=null, duration=25, currentSessionId=null, modalReqId=null, modalSourceId=null, toastTimer=null;
  let pendingDocument=null, documentImportBusy=false, studioSourceId=null;
  let outlookSettings={days:21,weekdayMinutes:25,weekendMinutes:60,missedDates:[]};
  const $=s=>document.querySelector(s);
  const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const fmtDate=date=>{try{return new Date(date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}catch{return date;}};
  const courseName=id=>db.courses.find(x=>x.id===id)?.name||'Unknown course';
  const reqById=id=>db.requirements.find(r=>r.id===id);
  const activeCount=id=>db.requirements.filter(r=>r.active&&r.courseId===id).length;
  const kindLabel=k=>({recall:'Recall',explain:'Explain',apply:'Apply'})[k]||'Explain';
  const rateLabel=r=>({again:'Again',hard:'Hard',good:'Good',easy:'Easy'})[r]||'New';
  const rClass=r=>({again:'warn',hard:'warn',good:'good',easy:'good'})[r]||'';
  function save(){Store.save(db,currentSessionId).catch(e=>notify('Saving failed: '+(e.message||'Check browser storage. Export a backup.'),true));}
  function notify(message,error=false){let old=$('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;document.body.appendChild(el);if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3800);}
  function transact(fn){try{const ret=fn();save();render();return ret;}catch(e){notify(e.message||'Something went wrong.',true);}}
  function courseOptions(selected='',placeholder='Select a course'){return `<option value="">${esc(placeholder)}</option>`+db.courses.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('');}
  function empty(title,desc,cta='',action=''){return `<div class="empty"><div class="bigemoji">✧</div><h2>${esc(title)}</h2><p>${esc(desc)}</p>${cta?`<button class="btn primary" data-action="${action}">${esc(cta)}</button>`:''}</div>`;}
  const nav=[['home','◫','Overview'],['capture','✎','Capture'],['study','◉','Study Now'],['courses','▤','Knowledge'],['assessments','▦','Assessments'],['forecast','◴','Calendar'],['insights','◷','Progress']];
  function sidebar(){return `<aside class="sidebar"><div class="brand"><span class="mark">✳</span><span>active<span style="color:#176d5e">recall</span></span></div><nav class="nav" aria-label="Main navigation">${nav.map(([key,icon,label])=>`<button class="navbtn ${page===key?'active':''}" data-action="navigate" data-page="${key}" ${page===key?'aria-current="page"':''}><span class="navicon">${icon}</span>${label}</button>`).join('')}</nav><div class="sidefoot"><strong><span class="statusdot"></span>100% free · Browser-local</strong><p>Hosted as a static site. No payments, API keys, accounts, or cloud sync. Export backups regularly.</p></div></aside>`;}
  function header(){return `<div class="topline"><div class="path">ACTIVE RECALL WEB <span style="color:#b7c4bd">/</span> ${esc(nav.find(x=>x[0]===page)?.[2]||'')}</div><div class="topright"><span class="tag">Blueprint 2.9 · Free</span><span class="avatar" aria-label="Local learner profile">A</span></div></div>`;}
  function shell(content){return `<div class="app">${sidebar()}<main class="main">${header()}${content}<div class="footer">Free &amp; static · Notes stay in this browser · Export backups · Review generated drafts before relying on them · <a href="./health.html">Site diagnostics</a></div></main></div>${modalReqId?editModal():''}${modalSourceId?editSourceModal():''}${studioSourceId?studioModal():''}`;}
  function dashboard(){const integrity=C.integrity(db);const s=C.stats(db),preview=C.planActivities(db,15).items.slice(0,4),topUpcoming=s.upcoming.slice(0,3);
    return `<div class="hero"><div><div class="eyebrow">Your learning, organised</div><h1>One place to learn.<br>One queue to remember.</h1><p>Add knowledge as you encounter it. Study across your courses without organising separate decks or planning every review.</p><div class="btnrow" style="margin-top:22px"><button class="btn primary" data-action="navigate" data-page="study">Start studying ↗</button><button class="btn secondary" data-action="navigate" data-page="capture">+ Add learning</button></div></div><span class="orb"></span><span class="orb2"></span></div>
    ${!db.courses.length?`<div class="section">${empty('Begin with your first course','Create your own course or explore a clearly labelled sample with biology, chemistry, mathematics and history.','Explore sample data','demo')}<div style="text-align:center;margin-top:12px"><button class="btn ghost small" data-action="navigate" data-page="courses">Create my own course →</button></div></div>`:''}
    <section class="section"><div class="grid cols4">${metric('Active courses',s.courses,'All subjects together')}${metric('Learning requirements',s.requirements,'Across courses')}${metric('Ready for review',s.due,'New + due recall targets')}${metric('Review attempts',db.attempts.length,'Self-rated prototype evidence')}</div></section>
    <section class="section grid cols2"><div class="card"><div class="card-title"><h2>Choose your study time</h2><span class="pill good">Adaptive queue</span></div><p class="muted small" style="margin-bottom:15px">The same unified system adjusts to a quick break or a longer study block.</p>${durationPicker()}<div class="btnrow" style="margin-top:15px"><button class="btn primary" data-action="start-session" ${!C.eligibleCandidates(db).length?'disabled':''}>Study for ${duration} min ↗</button></div></div><div class="card"><div class="card-title"><h2>Recommended next</h2><span class="pill">15-min preview</span></div>${preview.length?`<div class="list">${preview.map(p=>`<div class="listrow"><span class="roundicon">${courseName(p.req.courseId)[0]}</span><div class="rowbody"><strong>${esc(p.activity?.question||p.req.question)}</strong><small>${esc(courseName(p.req.courseId))} · ${p.isNew?'First attempt':p.due?'Due for review':'Additional practice'} · ${esc(p.target.label)}</small></div></div>`).join('')}</div>`:`<p class="muted">Add learning and confirm generated questions in Knowledge to make them available for review. Unverified drafts are never auto-scheduled.</p>`}</div></section>
    <section class="section grid cols2"><div class="card"><div class="card-title"><h2>Upcoming assessments</h2><button class="btn small secondary" data-action="navigate" data-page="assessments">Manage ↗</button></div>${topUpcoming.length?topUpcoming.map(a=>`<div class="listrow"><span class="roundicon">▦</span><div class="rowbody"><strong>${esc(a.title)}</strong><small>${esc(courseName(a.courseId))} · ${fmtDate(a.date)}</small></div><span class="pill ${C.daysUntil(a.date)<=3?'warn':''}">${C.daysUntil(a.date)===0?'Today':C.daysUntil(a.date)+'d'}</span></div>`).join(''):`<p class="muted">No upcoming assessments. Add exams to influence the study plan.</p>`}</div><div class="card"><div class="card-title"><h2>Learning integrity</h2><span class="pill blue">Source-first</span></div><p class="muted small">Every generated draft links to its original note. Confirm the question and reference answer before depending on it.</p><div class="sepline"></div><div class="listrow"><span class="roundicon">✎</span><div class="rowbody"><strong>${integrity.drafts} unverified locally generated drafts</strong><small>${integrity.needsReview} need closer review · ${integrity.possibleConflicts} potential contradictions · ${integrity.linkedRepeats} repeated statements linked. No AI used.</small></div></div><button class="btn secondary small" data-action="navigate" data-page="courses" style="margin-top:14px">Review requirements</button></div></section>`;
  }
  function metric(label,value,note){return `<div class="card slim"><div class="metric-label">${esc(label)}</div><div class="metric">${value}</div><div class="metric-note">${esc(note)}</div></div>`;}
  function durationPicker(){return `<div class="chips" role="group" aria-label="Study session duration">${[5,15,25,45,60,120].map(n=>`<button class="chip ${duration===n?'selected':''}" data-action="duration" data-minutes="${n}">${n<60?n+'m':n/60+'h'}</button>`).join('')}<label class="sr-only" for="custom-duration">Custom minutes</label><input id="custom-duration" class="input" style="width:110px;padding:7px 10px;min-height:35px" type="number" min="5" max="720" value="${duration}" aria-label="Custom session duration in minutes"/></div>`;}
  function documentOutlinePreview(){
    if(!pendingDocument)return '';
    const txt=$('#import-preview-text')?.value||pendingDocument.content;
    let entries=[];try{entries=Doc.buildOutline(txt,pendingDocument.format);}catch{return '';}
    const label=pendingDocument.format==='pdf'?'Page outline':'Document outline';
    return `<details class="document-outline" open><summary><strong>${label}</strong> <span class="muted small">${entries.length} section markers · select to locate in text</span></summary><div class="outline-items">${entries.slice(0,24).map(e=>`<button type="button" class="outline-jump" data-action="jump-outline" data-offset="${e.start}" aria-label="Go to ${esc(e.title)}"><span>${esc(e.title)}</span></button>`).join('')}${entries.length>24?`<p class="small muted">${entries.length-24} additional markers not shown</p>`:''}</div></details>`;
  }
  function importPanel(){
    const warning=pendingDocument?.warning?`<div class="note" role="status" style="margin-top:12px"><strong>PDF text extraction notice</strong><br>${esc(pendingDocument.warning)}</div>`:'';
    const audit=pendingDocument?.extractionAudit;
    const pageAudit=audit?`<details class="document-outline" open><summary><strong>PDF page integrity check</strong> <span class="muted small">${audit.pages.length} pages · ${(audit.missingPages||[]).length} without text</span></summary><div class="pdf-audit-list">${audit.pages.map(pg=>`<div class="pdf-audit-item"><strong>Page ${pg.page}</strong><span>${pg.missingText?'No extracted text':pg.characters.toLocaleString()+' extracted characters'}</span>${(pg.flags||[]).map(f=>`<span class="warningtext">${esc(f)}</span>`).join('')}</div>`).join('')}</div></details><label class="pdf-confirm"><input type="checkbox" name="pdfReviewed" value="yes" required/><span>I compared the extracted material with the original PDF and corrected important omissions or errors. Figures, formulas and page layout may need manual work.</span></label>${(audit.missingPages||[]).length?`<label class="pdf-confirm"><input type="checkbox" name="missingPagesAcknowledged" value="yes" required/><span><strong>Missing content:</strong> page(s) ${(audit.missingPages||[]).join(', ')} had no extractable text. I inspected those pages and either entered essential content in the text editor or accept that they will not be included in generated study material.</span></label>`:''}`:'';
    const preview=pendingDocument?`<form data-form="import-document" class="stack" style="margin-top:16px"><div class="import-summary"><strong>${esc(pendingDocument.name)}</strong><span class="pill">${pendingDocument.format.toUpperCase()}</span><span class="pill">${pendingDocument.characters.toLocaleString()} characters</span><span class="pill">${pendingDocument.chunks.length} source parts</span>${pendingDocument.pageCount?`<span class="pill">${pendingDocument.pageCount} PDF pages</span>`:''}</div><div class="field"><label for="import-course">Save under course</label><select class="select" id="import-course" name="courseId" required>${courseOptions(focusedCourse)}</select></div><div class="field"><label for="import-title">Source title</label><input class="input" id="import-title" name="title" maxlength="90" required value="${esc(pendingDocument.name.replace(/\.[^.]+$/,''))}"/></div><div class="field"><label for="import-preview-text">Review and correct extracted text before saving</label><textarea class="textarea import-preview" id="import-preview-text" name="content" rows="9" required maxlength="72000">${esc(pendingDocument.content)}</textarea><small>The entire extracted text will be stored in source-linked parts. Any incomplete formulas, tables, or columns should be corrected here. Generated questions stay drafts until reviewed.</small></div>${warning}${pageAudit}${documentOutlinePreview()}<div class="btnrow"><button type="submit" class="btn primary">Import source + draft recall ↗</button><button type="button" class="btn secondary" data-action="discard-document">Cancel import</button></div></form>`:'<p class="info" style="margin-top:12px">Choose a document to preview its text before saving. TXT and Markdown work offline. For PDFs, the app tries its limited offline reader first and asks permission before loading the free full PDF.js reader if necessary. Your file is not intentionally uploaded. Check imported text carefully.</p>';
    return `<section class="section"><div class="card"><div class="card-title"><h2>Import lecture files</h2><span class="pill good">Free · Local processing</span></div><div class="field"><label for="document-file">Choose a text, Markdown, or text-based PDF file</label><input class="input" id="document-file" type="file" accept=".txt,.md,.markdown,.pdf,text/plain,text/markdown,application/pdf" ${documentImportBusy?'disabled':''}/><small>12 MB/file maximum, up to 72,000 extracted characters or 80 PDF pages. Scanned PDFs and images require OCR and are not supported yet.</small><div class="field" style="margin-top:12px"><label for="pdf-mode">PDF reading mode</label><select id="pdf-mode" class="select"><option value="auto">Recommended: try offline, ask before free full-reader fallback</option><option value="offline">Offline only (limited, no downloads)</option><option value="full">Full PDF.js (free; internet needed first time)</option></select><small>Offline reader may fail on complex PDFs. Review text against the original. No PDF content is intentionally uploaded.</small></div></div>${documentImportBusy?'<div class="note" role="status" style="margin-top:12px">Extracting document locally…</div>':''}${preview}</div></section>`;
  }
  function capture(){if(!db.courses.length)return `<div class="pagehead"><div><div class="eyebrow">Learning capture</div><h1>Capture something new.</h1></div></div>${empty('Create a course first','A course provides context for source materials and new learning requirements.','Go to Knowledge','navigate-courses')}`;
    return `<div class="pagehead"><div><div class="eyebrow">Learning capture</div><h1>Capture what you learned.</h1><p>Paste a lecture summary, write something you learned, or import a document below. The original source is saved, and offline, source-linked practice drafts are proposed.</p></div></div><div class="twocol"><div class="card"><form id="capture-form" data-form="capture" class="stack"><div class="field"><label for="capture-course">Course</label><select class="select" name="courseId" id="capture-course" required>${courseOptions(focusedCourse)}</select></div><div class="field"><label for="capture-title">Title or lecture</label><input class="input" name="title" id="capture-title" placeholder="e.g. Lecture 8 — Enzyme kinetics" maxlength="120"/></div><div class="field"><label for="capture-text">What did you learn?</label><textarea class="textarea" name="content" id="capture-text" rows="12" required placeholder="Paste notes, write a quick summary, or capture the main ideas from today's class..."></textarea><small>Your original text stays preserved. Draft questions can be edited later.</small></div><div class="btnrow"><button class="btn primary" type="submit">Save learning + draft recall ↗</button></div></form></div><div class="stack"><div class="card"><div class="card-title"><h2>What happens next?</h2></div><div class="indexlist"><div><strong>1 · Preserve the original note</strong><div class="info">No silent rewriting or deletion.</div></div><div><strong>2 · Propose learning requirements</strong><div class="info">This local prototype uses simple sentence rules; always review.</div></div><div><strong>3 · Update the unified study queue</strong><div class="info">New requirements become available alongside all other classes.</div></div><div><strong>4 · Adapt after study</strong><div class="info">Self-rated attempts affect which questions are recommended.</div></div></div></div><div class="note"><strong>Scope of this prototype</strong><br>This local app proposes rule-based source-linked drafts. You can also define criteria for explanations and check them yourself after recall. It does not use AI grading, paid services, or calibrated mastery estimates.</div></div></div>${importPanel()}`;
  }
  function qualityPanel(report){
    if(!report)return '';
    const issues=report.flagged.filter(f=>f.issues.some(i=>i.code!=='unverified'));
    const needsSource=report.sourceRows.filter(r=>r.unrepresented>0);
    const reviewed=report.verified;
    const showSources=needsSource.slice(0,12),showIssues=issues.slice(0,8);
    return `<section class="quality-panel card slim" aria-label="Source and question review"><div class="card-title"><h3>Question quality & source coverage</h3><span class="pill blue">Read-only audit</span></div><p class="info" style="margin-bottom:10px">${esc(report.warning)} Only questions that you have verified can enter the automatic calendar.</p><div class="quality-stats"><div><strong>${report.totalSegments}</strong><span>Parseable statements</span></div><div><strong>${report.represented}</strong><span>Linked to questions</span></div><div><strong>${reviewed}</strong><span>Linked to verified questions</span></div><div><strong>${report.unrepresented}</strong><span>No mapped question</span></div></div><details class="quality-details"><summary><strong>Statements without mapped questions</strong> · ${report.unrepresented} across ${needsSource.length} source(s)</summary>${needsSource.length?showSources.map(row=>`<div class="quality-row"><strong>${esc(row.title)}</strong> <span class="small muted">${row.unrepresented}/${row.segments} unmapped</span><button class="btn secondary small" type="button" data-action="edit-source" data-id="${esc(row.sourceId)}">Inspect source</button><button class="btn secondary small" type="button" data-action="open-question-studio" data-id="${esc(row.sourceId)}">Suggest source-backed questions</button>${row.examples.map(e=>`<p class="small muted">${esc(e.text.length>185?e.text.slice(0,185)+'…':e.text)}</p>`).join('')}</div>`).join(''):'<p class="small muted">No unmapped parseable statements detected. Important topics, formulas, figures and unstated learning goals may still be missing.</p>'}${needsSource.length>showSources.length?`<p class="small muted">${needsSource.length-showSources.length} more source(s) have unmapped statements. Review the saved source notes below.</p>`:''}<button class="btn secondary small" type="button" data-action="add-manual">+ Add a meaningful question</button></details><details class="quality-details"><summary><strong>Question wording and source warnings</strong> · ${issues.length} item(s)</summary>${issues.length?showIssues.map(f=>`<div class="quality-row"><strong>${esc(f.question.length>175?f.question.slice(0,175)+'…':f.question)}</strong><p class="small muted">${esc(f.issues.filter(i=>i.code!=='unverified').map(i=>i.label).join(' · '))}</p><button class="btn secondary small" type="button" data-action="edit-requirement" data-id="${esc(f.requirementId)}">Review / edit question</button></div>`).join(''):'<p class="small muted">No structural wording warnings detected. That does not establish scientific accuracy or educational validity.</p>'}${issues.length>showIssues.length?`<p class="small muted">${issues.length-showIssues.length} other flagged question(s) remain in this course's requirements below.</p>`:''}</details></section>`;
  }
  function courses(){if(!focusedCourse&&db.courses.length)focusedCourse=db.courses[0].id;const course=db.courses.find(c=>c.id===focusedCourse),reqs=course?db.requirements.filter(r=>r.courseId===course.id):[],sources=course?db.sources.filter(s=>s.courseId===course.id):[],quality=course?C.questionCoverage(db,course.id):null;
    return `<div class="pagehead"><div><div class="eyebrow">Knowledge base</div><h1>Every course, connected.</h1><p>Manage interconnected learning requirements, distinct recall focuses, alternative question variations, and learner-reviewed explanation rubrics—without separate decks.</p></div></div><div class="twocol knowledge-layout"><div class="stack"><div class="card slim"><h3 style="margin-bottom:12px">Your courses</h3>${db.courses.map(c=>`<button class="coursebtn ${focusedCourse===c.id?'active':''}" data-action="focus-course" data-id="${c.id}"><span class="courseitem"><strong>${esc(c.name)}</strong><small class="muted">${activeCount(c.id)} requirements</small></span><span>›</span></button>`).join('')||'<p class="muted small">No courses yet.</p>'}</div><div class="card slim"><form data-form="add-course" class="stack"><div class="field"><label for="new-course">Add a course</label><input class="input" id="new-course" name="name" maxlength="80" required placeholder="e.g. Physics"/></div><button class="btn primary block" type="submit">+ Create course</button></form></div></div><div>${course?`<div class="card"><div class="card-title"><div><div class="eyebrow">COURSE</div><h2 style="margin-top:3px">${esc(course.name)}</h2></div><button class="btn secondary small" data-action="add-manual">+ Add question</button></div><div class="note" style="margin-bottom:15px">Offline-generated prompts are drafts, not verified learning objectives. Review them, especially flagged statements. No paid API, network inference, or AI grading is used.</div>${qualityPanel(quality)}<h3 style="margin-bottom:8px">Learning requirements (${reqs.filter(r=>r.active).length})</h3><div class="note" style="margin-bottom:10px">${reqs.filter(r=>r.active&&r.origin==='rule_draft'&&!r.verifiedAt&&!r.reviewedAt).length} draft(s) need verification. Potential duplicates or contradictions are explicitly flagged and held out of the study queue until verified. Verified drafts keep their source references and review history.</div>${reqs.filter(r=>r.active).length?reqs.filter(r=>r.active).map(r=>requirementRow(r)).join(''):empty('No requirements yet','Capture a note or add a question manually.','Add learning','navigate-capture')}
    <div class="sepline"></div><h3 style="margin-bottom:10px">Source notes (${sources.length})</h3>${sources.length?sources.slice().reverse().map(s=>`<button class="btn secondary small" data-action="edit-source" data-id="${esc(s.id)}" style="margin:12px 0 2px">Edit source · v${s.version||1}</button><button class="btn secondary small" data-action="open-question-studio" data-id="${esc(s.id)}" style="margin:12px 0 2px 7px">Question Studio ↗</button><details style="border-bottom:1px solid var(--line);padding:10px 0"><summary style="cursor:pointer;font-weight:750">${esc(s.title)} <span class="muted small">· ${new Date(s.createdAt).toLocaleDateString()}</span></summary><div class="note" style="margin-top:10px;white-space:pre-wrap">${esc(s.content)}${s.duplicateLinks?.length?`<div class="reqmeta"><span class="pill good">${s.duplicateLinks.length} repeated statement(s) linked to earlier requirements</span></div>`:''}${s.conflictLinks?.length?`<div class="reqmeta"><span class="pill warn">${s.conflictLinks.length} potentially conflicting statement(s) — inspect drafts</span></div>`:''}</div></details>`).join(''):'<p class="muted small">No saved notes for this course.</p>'}</div>`:empty('Choose or create a course','Begin by adding a subject, then capture learning and generate study activities.')}</div></div>`;
  }
  function requirementRow(r){
    const source=db.sources.find(s=>s.id===r.sourceId),targets=C.getTargets(db,r.id,{includePending:true});
    const unverified=r.origin==='rule_draft'&&!r.verifiedAt&&!r.reviewedAt;
    const reviewFlag=r.confidence==='review'&&unverified;
    const flags=`${r.sourceRevisionPending?'<span class="pill warn">Source revised · verify</span>':''}${unverified?'<span class="pill warn">Unverified draft</span>':''}${reviewFlag?'<span class="pill warn">Review wording</span>':''}${r.possibleDuplicateOf?'<span class="pill warn">Possible overlap</span>':''}${r.possibleConflictWith?'<span class="pill warn">Possible contradiction</span>':''}`;
    const focusRows=targets.map(t=>{
      const m=C.getMemory(db,r.id,t.id),variants=C.getActivities(db,r.id,t.id),extras=variants.filter(a=>!a.isPrimary),rubric=C.getCriteria(db,t.id,{includePending:true});
      return `<div class="focusrow"><div class="focushead"><div><strong>${esc(t.label)}</strong>${t.isPrimary?' <span class="pill">Original focus</span>':''}${t.needsReview?' <span class="pill warn">Verify after revision</span>':''}<div class="small muted">${variants.length} ${variants.length===1?'question':'questions'} · ${rubric.length} rubric ${rubric.length===1?'point':'points'} · ${m?`Next review ${new Date(m.dueAt).toLocaleDateString()}`:'Not yet reviewed'}</div></div><div class="btnrow">${t.needsReview?`<button class="btn secondary small" data-action="verify-focus" data-id="${esc(t.id)}">Verify focus</button>`:''}<button class="btn secondary small" data-action="manage-rubric" data-id="${esc(r.id)}" data-target-id="${esc(t.id)}">Rubric</button><button class="btn secondary small" data-action="add-variation" data-id="${esc(r.id)}" data-target-id="${esc(t.id)}">+ Variation</button></div></div><div class="small">${esc(variants.find(a=>a.isPrimary)?.question||'No active question')}</div>${extras.length?`<details class="variantlist"><summary>${extras.length} alternative ${extras.length===1?'question':'questions'}</summary>${extras.map(a=>`<div class="listrow"><div class="rowbody"><strong>${esc(a.question)}</strong><small>${esc(a.answer)} · ${kindLabel(a.kind)}</small></div><button class="btn danger small" data-action="archive-variation" data-id="${esc(a.id)}">Archive</button></div>`).join('')}</details>`:''}</div>`;
    }).join('');
    return `<div class="reqrow"><span class="roundicon">${r.kind==='recall'?'?':r.kind==='apply'?'↗':'✦'}</span><div class="rowbody"><div class="eyebrow">LEARNING REQUIREMENT</div><strong>${esc(r.objective||r.question)}</strong><p>${esc(r.answer)}</p><div class="reqmeta"><span class="pill">${kindLabel(r.kind)}</span>${flags}<span class="pill blue">${targets.length} recall ${targets.length===1?'focus':'focus areas'}</span>${source?`<span class="pill blue">${esc(source.title)} · cited v${r.sourceVersion||1}</span>`:''}</div><div class="focusareas">${focusRows}</div></div><div class="stack" style="gap:6px;align-items:end">${unverified||r.sourceRevisionPending?`<button class="btn secondary small" data-action="verify-requirement" data-id="${esc(r.id)}">Verify</button>`:''}<button class="btn secondary small" data-action="add-focus" data-id="${esc(r.id)}">+ Recall focus</button><button class="btn secondary small" data-action="edit-requirement" data-id="${esc(r.id)}">Edit</button></div></div>`;
  }
  function studioModal(){
    const source=db.sources.find(s=>s.id===studioSourceId);
    if(!source)return '';
    const result=C.questionStudio(db,source.id,{limit:36});
    const proposals=result.candidates.slice(0,30);
    return `<div class="modalwrap"><div class="modal question-studio" role="dialog" aria-modal="true" aria-label="Question Studio"><div class="modalhead"><div><div class="eyebrow">SOURCE-GROUNDED · OFFLINE · REVIEW REQUIRED</div><h2>Question Studio</h2></div><button class="close" data-action="close-modal" aria-label="Close">×</button></div>
      <p class="small muted" style="margin-bottom:9px">${esc(source.title)} · source revision ${source.version||1} · ${proposals.length} structured proposal(s)</p>
      <div class="note" style="margin-bottom:13px"><strong>These are candidate questions, not verified learning objectives.</strong> Each reference answer is an exact source excerpt. Check accuracy, wording and whether the question genuinely tests that excerpt. Unsupported or unstructured statements are not invented. Saving a proposal creates or revises an <strong>unverified</strong> draft; it will not enter the calendar until you approve it.</div>
      <div class="studio-list">${proposals.length?proposals.map(p=>`<div class="studio-proposal"><div class="reqmeta"><span class="pill blue">${esc(p.structure.replaceAll('_',' '))}</span>${p.represented?`<span class="pill">Already mapped in source</span>`:`<span class="pill good">Previously unmapped</span>`}</div><strong>${esc(p.question)}</strong><p class="small muted"><strong>Source answer:</strong> ${esc(p.sourceQuote)}</p><div class="btnrow" style="margin-top:9px">${p.alreadySaved?`<span class="muted small">Exact question already saved</span>`:`<button class="btn secondary small" type="button" data-action="adopt-question-proposal" data-source-id="${esc(source.id)}" data-key="${esc(p.key)}">${p.improvableRequirementId?'Improve existing draft':'Review this draft'} →</button>`}</div></div>`).join(''):`<p class="muted">No sufficiently structured relationships were detected in this source. Write a question manually, or add a more explicit account of the mechanism, contrast, condition, or definition in your notes.</p>`}</div>
      <p class="small muted" style="margin-top:12px">This offline system recognises only explicit English sentence patterns. It cannot determine whether the science is correct, whether a document has adequate curriculum coverage, or whether a source-only answer is complete. No AI or paid API is used.</p></div></div>`;
  }
  function editModal(){
    if(modalReqId?.startsWith('rubric:')){
      const [,rid,tid]=modalReqId.split(':');
      const r=reqById(rid),target=(db.retrievalTargets||[]).find(t=>t.id===tid&&t.requirementId===rid);
      if(!r||!target)return '';
      const criteria=C.getCriteria(db,tid,{includePending:true});
      return `<div class="modalwrap"><div class="modal" role="dialog" aria-modal="true" aria-label="Manage recall rubric"><div class="modalhead"><div><div class="eyebrow">LEARNER-REVIEWED CRITERIA</div><h2>Explanation checklist</h2></div><button class="close" data-action="close-modal" aria-label="Close">×</button></div><div class="note"><strong>${esc(target.label)}</strong><br>Add specific ideas, relationships, or reasoning steps you expect in a good explanation. Criteria are checked by you—this offline app does not grade your answer automatically. The free suggestion button extracts exact source excerpts; generated points remain inactive until you verify them. Editing a point retains earlier checks under its earlier version.</div><div class="stack" style="margin-top:15px">${criteria.length?criteria.map(c=>`<div class="criterion-edit"><form data-form="revise-criterion" class="stack" style="gap:7px"><input type="hidden" name="id" value="${esc(c.id)}"/><label class="small muted" for="criterion-text-${esc(c.id)}">Criterion · v${c.version}${c.needsReview?' · requires verification':''}${c.origin==='offline_criterion_draft'?' · offline source suggestion':''}</label>${c.sourceQuote?`<p class="small muted">Source excerpt: “${esc(c.sourceQuote)}”</p>`:''}<textarea id="criterion-text-${esc(c.id)}" name="text" class="textarea" style="min-height:65px" maxlength="240" required>${esc(c.text)}</textarea><div class="btnrow"><button class="btn secondary small" type="submit">Save wording</button>${c.needsReview?`<button class="btn secondary small" type="button" data-action="verify-criterion" data-id="${esc(c.id)}">Verify</button>`:''}<button class="btn danger small" type="button" data-action="archive-criterion" data-id="${esc(c.id)}">Archive</button></div></form></div>`).join(''):'<p class="muted small">No checklist criteria yet. Without criteria, the app still supports self-rated recall.</p>'}<div class="note"><strong>Suggest checkpoints for free</strong><br>Uses conservative text rules on this focus’s existing note excerpt or reference answer. Suggestions must be checked for accuracy and usefulness before they can appear in study.</div><button class="btn secondary" data-action="suggest-criteria" data-target-id="${esc(tid)}" type="button">✧ Suggest from source / answer (offline)</button><form data-form="add-criterion" class="stack"><input type="hidden" name="targetId" value="${esc(tid)}"/><div class="field"><label for="new-criterion">Add a required explanation point</label><textarea id="new-criterion" class="textarea" name="text" maxlength="240" style="min-height:85px" placeholder="e.g. Explains how transition-state stabilisation lowers the activation-energy barrier" required></textarea></div><button class="btn primary" type="submit">+ Add checklist point</button></form></div><div class="btnrow" style="margin-top:14px"><button class="btn secondary" data-action="close-modal">Done</button></div></div></div>`;
    }
    if(modalReqId?.startsWith('focus:')){
      const r=reqById(modalReqId.slice(6));if(!r)return '';
      return `<div class="modalwrap"><div class="modal" role="dialog" aria-modal="true" aria-label="Add recall focus"><div class="modalhead"><div><div class="eyebrow">NEW DISTINCT RETRIEVAL TARGET</div><h2>Add recall focus</h2></div><button class="close" data-action="close-modal" aria-label="Close">×</button></div><div class="note">Create a separate focus only when this is meaningfully different knowledge that should have its own review schedule. To reword an existing question, use + Variation instead.</div><form data-form="add-focus" class="stack" style="margin-top:15px"><input type="hidden" name="requirementId" value="${esc(r.id)}"/><div class="field"><label>Focus label</label><input class="input" name="label" required maxlength="160" placeholder="e.g. Explain membrane permeability"/></div><div class="field"><label>Independent recall question</label><textarea class="textarea" name="question" required maxlength="500"></textarea></div><div class="field"><label>Reference answer</label><textarea class="textarea" name="answer" required maxlength="4000"></textarea></div><div class="field"><label>Practice type</label><select class="select" name="kind">${['recall','explain','apply'].map(k=>`<option value="${k}" ${r.kind===k?'selected':''}>${kindLabel(k)}</option>`).join('')}</select></div><div class="btnrow"><button class="btn primary" type="submit">Add recall focus</button><button class="btn secondary" type="button" data-action="close-modal">Cancel</button></div></form></div></div>`;
    }
    if(modalReqId?.startsWith('variant:')){
      const [,rid,tid]=modalReqId.split(':');const r=reqById(rid),target=C.getTargets(db,rid,{includePending:true}).find(t=>t.id===tid);if(!r||!target)return '';
      const base=C.getActivities(db,r.id,target.id).find(a=>a.isPrimary);
      return `<div class="modalwrap"><div class="modal" role="dialog" aria-modal="true" aria-label="Add question variation"><div class="modalhead"><div><div class="eyebrow">SAME RECALL FOCUS · DIFFERENT QUESTION</div><h2>Add a question variation</h2></div><button class="close" data-action="close-modal" aria-label="Close">×</button></div><p class="muted small">The new prompt shares the focus area's review history, not a separate due date. Ensure it tests the same underlying idea.</p><div class="note"><strong>Focus</strong><br>${esc(target.label)}</div><form data-form="add-variation" class="stack" style="margin-top:14px"><input type="hidden" name="requirementId" value="${esc(r.id)}"/><input type="hidden" name="targetId" value="${esc(target.id)}"/><div class="field"><label>Alternative question</label><textarea class="textarea" name="question" required maxlength="500" placeholder="Ask about the same knowledge in a different way..."></textarea></div><div class="field"><label>Reference answer</label><textarea class="textarea" name="answer" required maxlength="4000">${esc(base?.answer||r.answer)}</textarea></div><div class="field"><label>Question format</label><select class="select" name="kind">${['recall','explain','apply'].map(k=>`<option value="${k}" ${base?.kind===k?'selected':''}>${kindLabel(k)}</option>`).join('')}</select></div><div class="btnrow"><button class="btn primary" type="submit">Add variation</button><button class="btn secondary" type="button" data-action="close-modal">Cancel</button></div></form></div></div>`;
    }
    const r=reqById(modalReqId),isNew=modalReqId==='new';if(!r&&!isNew)return '';
    const cid=isNew?focusedCourse:r.courseId;
    return `<div class="modalwrap" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-label="${isNew?'Add a question':'Edit a learning requirement'}"><div class="modalhead"><div><div class="eyebrow">${isNew?'New learning requirement':'Requirement revision'}</div><h2 style="margin-top:6px">${isNew?'Add your own question':'Edit question and answer'}</h2></div><button class="close" data-action="close-modal" aria-label="Close">×</button></div><form data-form="save-requirement" class="stack"><input type="hidden" name="id" value="${isNew?'':esc(r.id)}"/><input type="hidden" name="courseId" value="${esc(cid||'')}"/><div class="field"><label>Learning objective</label><input class="input" name="objective" maxlength="300" placeholder="What should you be able to know or do?" value="${isNew?'':esc(r.objective||r.question)}"/></div><div class="field"><label>Question or learning task</label><textarea class="textarea" style="min-height:90px" name="question" required maxlength="500">${isNew?'':esc(r.question)}</textarea></div><div class="field"><label>Reference answer</label><textarea class="textarea" style="min-height:120px" name="answer" required maxlength="4000">${isNew?'':esc(r.answer)}</textarea></div><div class="field"><label>Practice type</label><select class="select" name="kind">${['recall','explain','apply'].map(k=>`<option value="${k}" ${!isNew&&r.kind===k?'selected':''}>${kindLabel(k)}</option>`).join('')}</select></div>${!isNew&&r.sourceQuote?`<div class="note"><strong>Source excerpt</strong><br>${esc(r.sourceQuote)}</div>`:''}<div class="field"><label for="edit-change-type">Type of revision</label><select class="select" id="edit-change-type" name="changeType"><option value="substantive">Changes what must be learned (reset review interval)</option><option value="wording">Only rewords the same idea (keep review interval)</option></select></div><div class="note">Earlier attempt records always remain preserved. Only choose wording-only when the evidence and learning target are genuinely unchanged.</div><div class="btnrow"><button class="btn primary" type="submit">Save requirement</button><button class="btn secondary" type="button" data-action="close-modal">Cancel</button></div></form></div></div>`;
  }
  function editSourceModal(){
    const source=db.sources.find(s=>s.id===modalSourceId);if(!source)return '';
    const history=(db.sourceVersions||[]).filter(v=>v.sourceId===source.id).sort((a,b)=>b.version-a.version);
    return `<div class="modalwrap"><div class="modal" role="dialog" aria-modal="true" aria-label="Edit source notes"><div class="modalhead"><div><div class="eyebrow">SOURCE HISTORY · v${source.version||1}</div><h2>Edit lecture notes</h2></div><button class="close" data-action="close-modal" aria-label="Close">×</button></div><form data-form="save-source" class="stack"><input type="hidden" name="id" value="${esc(source.id)}"/><div class="field"><label>Source title</label><input class="input" name="title" required maxlength="120" value="${esc(source.title)}"/></div><div class="field"><label>Original notes</label><textarea class="textarea" name="content" rows="8" required>${esc(source.content)}</textarea></div>${source.documentOutline?.length?`<details class="document-outline"><summary><strong>Source outline</strong> <span class="small muted">${source.documentOutline.length} headings or pages · select to navigate</span></summary><div class="outline-items">${source.documentOutline.slice(0,40).map(x=>`<button type="button" class="outline-jump" data-action="jump-source-outline" data-offset="${x.start}">${esc(x.title)}</button>`).join('')}</div></details>`:''}<div class="note">Saving a changed source creates a new version. Previously generated requirements stay linked to their earlier excerpts and are held for review until you confirm them. Your study attempts are preserved; this edit does not silently rewrite questions.</div><div class="btnrow"><button class="btn primary" type="submit">Save new source version</button><button class="btn secondary" type="button" data-action="close-modal">Cancel</button></div></form><details style="margin-top:14px"><summary>See ${history.length} source version${history.length===1?'':'s'}</summary>${history.map(v=>`<div class="note" style="margin:10px 0"><strong>Version ${v.version}</strong> · ${esc(v.title)}<div style="white-space:pre-wrap;margin-top:7px">${esc(v.content)}</div></div>`).join('')}</details></div></div>`;
  }
  function assessments(){const assessments=db.assessments.slice().sort((a,b)=>a.date.localeCompare(b.date));
    return `<div class="pagehead"><div><div class="eyebrow">Deadline-aware study</div><h1>Assessments shape your plan.</h1><p>Upcoming exams affect priorities across all courses without requiring you to create a separate study deck.</p></div></div><div class="twocol assessment-layout"><div class="card"><div class="card-title"><h2>Add an assessment</h2></div><form data-form="add-assessment" class="stack"><div class="field"><label>Assessment name</label><input class="input" name="title" required placeholder="e.g. Chemistry Unit 4 exam"/></div><div class="field"><label>Course</label><select class="select" name="courseId" id="assessment-course" required>${courseOptions()}</select></div><div class="field"><label>Date</label><input class="input" type="date" name="date" value="${C.addDays(new Date(),7)}" required/></div><div class="field"><label>Scope</label><select class="select" name="scope" id="assessment-scope"><option value="all">Entire course (prototype default)</option><option value="selected">Choose specific requirements</option></select><small>Entire course is a coarse proxy. Choose specific objectives when possible.</small></div><div id="assessment-selection" class="hidden"></div><button class="btn primary" type="submit" ${!db.courses.length?'disabled':''}>Add assessment</button></form></div><div class="card"><div class="card-title"><h2>Assessment timeline</h2></div>${assessments.length?assessments.map(a=>{const d=C.daysUntil(a.date),coverage=C.assessmentCoverage(db,a);return `<div class="listrow"><span class="roundicon">▦</span><div class="rowbody"><strong>${esc(a.title)}</strong><small>${esc(courseName(a.courseId))} · ${fmtDate(a.date)}</small><div class="reqmeta"><span class="pill">${a.scope==='all'?'All course requirements':a.requirementIds.length+' selected requirements'}</span><span class="pill">${coverage.total} recall targets</span><span class="pill good">${coverage.selfReported} self-reported success</span><span class="pill warn">${coverage.unattempted} unattempted · ${coverage.needsPractice} needs practice${coverage.blocked?' · '+coverage.blocked+' held for review':''}</span></div><small>Estimated time to attempt unresolved targets once: ~${coverage.estimatedPracticeMinutes} min (not an exam-readiness prediction). Of the self-rated Good/Easy attempts, ${coverage.selfReportedWritten} included written responses; ${coverage.selfReportedOral+coverage.selfReportedMental} were oral or unrecorded. None has been automatically graded. Rubric: ${coverage.rubricAllMet} target(s) with all points self-marked included, ${coverage.rubricGaps} with reported gaps, ${coverage.rubricUnassessed} with unchecked points${coverage.rubricHeld?', '+coverage.rubricHeld+' held points':''}.</small></div><div class="push"><span class="pill ${d>=0&&d<=3?'warn':''}">${d<0?'Past':d===0?'Today':d+' days'}</span></div><button class="btn ghost small" title="Remove assessment" data-action="delete-assessment" data-id="${a.id}">×</button></div>`;}).join(''):empty('No assessments yet','Add an upcoming exam or quiz to influence scheduling.')}</div></div>`;
  }
  function assessmentSelection(){const courseId=$('#assessment-course')?.value,scope=$('#assessment-scope')?.value,target=$('#assessment-selection');if(!target)return;if(scope!=='selected'){target.classList.add('hidden');target.innerHTML='';return;}target.classList.remove('hidden');const list=db.requirements.filter(r=>r.active&&r.courseId===courseId);target.innerHTML=`<div class="note"><strong>Select assessment content</strong>${list.length?list.map(r=>`<label class="checkline"><input type="checkbox" name="requirementIds" value="${r.id}"/>${esc(r.question)}</label>`).join(''):'<p>No requirements in this course yet.</p>'}</div>`;}
  function session(){let se=activeSession();if(se&&se.status==='active')return sessionActive(se);if(se&&se.status==='completed')return sessionCompleted(se);
    const s=C.stats(db),plan=C.planActivities(db,duration),counts={};plan.items.forEach(p=>counts[p.req.courseId]=(counts[p.req.courseId]||0)+1);
    return `<div class="pagehead"><div><div class="eyebrow">Unified adaptive queue</div><h1>Study what matters next.</h1><p>Choose the time you have. We'll assemble a feasible session from across your courses.</p></div></div><div class="sessionpanel"><div class="card"><h2 style="margin-bottom:8px">How long can you study?</h2><p class="muted small" style="margin-bottom:19px">Custom durations from 5 minutes to 12 hours are supported in this prototype.</p>${durationPicker()}<div class="sepline"></div><div class="card-title"><h2>Proposed session</h2><span class="pill good">${plan.items.length} activities</span></div>${plan.items.length?`<div class="list">${Object.entries(counts).map(([cid,n])=>`<div class="listrow"><span class="roundicon">${courseName(cid)[0]}</span><div class="rowbody"><strong>${esc(courseName(cid))}</strong><small>${n} ${n===1?'activity':'activities'} · selected automatically</small></div></div>`).join('')}</div>`:'<p class="muted">Add learning requirements or increase the time budget to begin.</p>'}<div class="note" style="margin:15px 0"><strong>Why these?</strong><br>${plan.items.slice(0,4).map(p=>`${esc(courseName(p.req.courseId))} · ${esc(p.target.label)} — ${esc(p.reasons.join('; '))}`).join('<br>')||'Add eligible learning requirements to see a schedule.'}</div><div class="note" style="margin:20px 0 15px">Reference answers are revealed after your attempt. You rate your own recall in this local version; no AI evaluation is performed.</div><button class="btn primary block" data-action="start-session" ${!plan.items.length||!s.requirements?'disabled':''}>Start ${duration}-minute session ↗</button></div></div>`;
  }
  function activeSession(){return db.sessions.find(s=>s.id===currentSessionId);}
  function sessionElapsedMs(se,now=Date.now()){return Math.max(0,(se.elapsedMs||0)+(se.paused?0:Math.max(0,now-(se.runningSince||now))));}
  function sessionRemainingMs(se,now=Date.now()){return Math.max(0,se.budgetMinutes*60000-sessionElapsedMs(se,now));}
  function timeStr(ms){const s=Math.ceil(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
  function sessionActive(se){const req=reqById(se.currentReqId),target=C.getTargets(db,se.currentReqId,{includePending:true}).find(t=>t.id===se.currentTargetId),activity=db.activities.find(a=>a.id===se.currentActivityId)||C.chooseActivity(db,se.currentReqId,se.currentTargetId),criteria=C.getCriteria(db,se.currentTargetId),heldCriteria=C.getCriteria(db,se.currentTargetId,{includePending:true}).filter(c=>c.needsReview).length,rem=sessionRemainingMs(se),progress=Math.min(100,sessionElapsedMs(se)/(se.budgetMinutes*60000)*100);if(!req)return sessionCompleted(se);
    return `<div class="sessionpanel"><div class="pagehead"><div><div class="eyebrow">One queue · All subjects</div><h1>Your study session</h1></div><div class="timer" id="study-timer">${timeStr(rem)}</div></div><div class="progress"><span id="study-progress" style="width:${progress}%"></span></div><div class="btnrow" style="margin:16px 0 22px"><span class="pill">${se.completedIds.length} completed</span><button class="btn secondary small" data-action="${se.paused?'resume-session':'pause-session'}">${se.paused?'▶ Resume':'Ⅱ Pause'}</button><button class="btn secondary small" data-action="extend-session" data-minutes="5">+5 min</button><button class="btn secondary small" data-action="extend-session" data-minutes="15">+15 min</button><button class="btn ghost small" data-action="remaining-five">5 min left</button><button class="btn danger small" data-action="finish-session">Finish</button></div><div class="card"><div class="card-title"><span class="pill good">${esc(courseName(req.courseId))}</span><span class="muted small">${kindLabel(activity?.kind||req.kind)} · variation ${Math.max(1,C.getActivities(db,req.id,target?.id).findIndex(a=>a.id===activity?.id)+1)}/${C.getActivities(db,req.id,target?.id).length} · ~${Math.max(1,Math.round(C.durationEstimate(db,activity||req).seconds/60))} min ${C.durationEstimate(db,activity||req).personalized?'· informed by your pace':'· starting estimate'}</span></div><div class="note" style="margin-bottom:14px"><strong>Why this activity?</strong><br>${esc(C.eligibleCandidates(db).find(x=>x.target.id===target?.id)?.reasons.join(" · ")||"Selected from your unified learning plan")}</div><div class="eyebrow">RECALL FOCUS · ${esc(target?.label||req.objective||req.question)}</div><h2 class="question">${esc(activity?.question||req.question)}</h2><label class="small muted" for="study-response">Your answer (optional for oral recall)</label><textarea id="study-response" class="textarea" style="margin-top:7px;min-height:120px" placeholder="Try to explain it before viewing the reference answer..." ${se.paused?'disabled':''}>${esc(se.draftAnswer||'')}</textarea>${se.showHint?`<div class="hintbox" style="margin-top:13px"><strong>Source clue</strong><br>${esc(req.kind==='recall'?'Think about the defining attribute or relationship in your notes.':req.kind==='apply'?'Identify what the situation asks, then connect it to the relevant principle.':'Identify the key relationship, mechanism, or evidence before explaining it.')}</div>`:''}${se.showReference?`<div class="answerbox" style="margin-top:15px"><strong>Reference answer</strong><br>${esc(activity?.answer||req.answer)}${req.sourceQuote?`<div class="sepline"></div><span class="small muted">Original source: ${esc(db.sources.find(x=>x.id===req.sourceId)?.title||'Lecture note')}</span>`:''}</div>${criteria.length?`<div class="rubric-checklist"><div class="rubric-title"><strong>Check your explanation</strong><span class="pill blue">${criteria.length} points</span></div><p class="info" style="margin-bottom:12px">Mark what your answer included, omitted, or left uncertain. Your own checks, not automated grading, inform the next review interval. Unmarked points remain unassessed.</p>${criteria.map(c=>`<fieldset class="criterion-check"><legend>${esc(c.text)}</legend><div class="criterion-options">${[['met','Included'],['missed','Missed'],['unsure','Not sure']].map(([status,label])=>`<label><input type="radio" data-criterion-id="${esc(c.id)}" name="check_${esc(c.id)}" value="${status}" ${se.criterionDraft?.[c.id]===status?'checked':''} ${se.paused?'disabled':''}/> ${label}</label>`).join('')}</div></fieldset>`).join('')}</div>`:''}${heldCriteria?`<p class="info warningtext" style="margin-top:12px">${heldCriteria} checklist point(s) await verification after a change. They are not used to score this attempt.</p>`:''}<p class="info" style="margin:16px 0 9px">Rate what you could recall independently. A rating updates a simple review heuristic, not an AI mastery score.</p><div class="field" style="margin:12px 0"><label for="response-mode">How did you answer?</label><select class="select" id="response-mode"><option value="auto">Automatically classify (typed or mental)</option><option value="oral">Spoke my answer aloud</option><option value="mental">Recalled mentally without writing</option></select><small>This helps describe the evidence; it does not change your rating.</small></div><div class="ratings">${[['again','Again'],['hard','Hard'],['good','Good'],['easy','Easy']].map(([r,l])=>`<button class="ratingbtn ${r}" data-action="rate" data-rating="${r}" ${se.paused?'disabled':''}>${l}</button>`).join('')}</div>`:`<div class="btnrow" style="margin-top:16px"><button class="btn secondary" data-action="hint" ${se.showHint||se.paused?'disabled':''}>◉ Get hint</button><button class="btn primary" data-action="reveal" ${se.paused?'disabled':''}>Reveal reference answer →</button></div>`}</div><p class="info" style="margin-top:12px">Saved in your browser as you type. A hint is recorded as assistance. Only confirmed questions enter study. Self-ratings are not AI grading.</p></div>`;
  }
  function sessionCompleted(se){const attempts=db.attempts.filter(a=>a.sessionId===se.id);const counts={};attempts.forEach(a=>counts[a.courseId]=(counts[a.courseId]||0)+1);
    return `<div class="sessionpanel"><div class="pagehead"><div><div class="eyebrow">Session summary</div><h1>Practice complete.</h1><p>Your responses have been saved, and future review dates have been updated.</p></div></div><div class="card"><div class="grid cols3">${metric('Activities',attempts.length,'Completed this session')}${metric('Courses',Object.keys(counts).length,'Represented in your work')}${metric('Assisted',attempts.filter(a=>a.assisted).length,'Used a source hint')}</div><div class="sepline"></div><h3 style="margin-bottom:8px">What you practised</h3>${attempts.length?attempts.map(a=>`<div class="listrow"><span class="roundicon">${courseName(a.courseId)[0]}</span><div class="rowbody"><strong>${esc(a.questionSnapshot||reqById(a.requirementId)?.question||'Question')}</strong><small>${esc(courseName(a.courseId))} · Self-rated ${rateLabel(a.rating)}${a.assisted?' · Hint used':''}${a.criterionChecks?.length?' · '+a.criterionChecks.filter(x=>x.status==='met').length+'/'+a.criterionChecks.length+' criteria self-marked included':''}${a.scheduleRating&&a.rating!==a.scheduleRating?' · Review interval shortened due to reported gap':''} · ${C.inputModeFor(a)==='written'?'Written answer':C.inputModeFor(a)==='oral'?'Spoken (self-reported)':'Unrecorded recall'}${a.durationSeconds?' · '+Math.round(a.durationSeconds)+'s active time':''}</small></div></div>`).join(''):'<p class="muted">No activities were completed.</p>'}<div class="note" style="margin:18px 0">This summary reports your activity and optional learner-marked explanation criteria, not an automated grade, validated mastery percentage, or predicted exam grade. The app will use the saved ratings to recommend future reviews.</div><div class="btnrow"><button class="btn primary" data-action="new-session">Plan another session ↗</button><button class="btn secondary" data-action="navigate" data-page="insights">Review history</button></div></div></div>`;
  }
  function insights(){const s=C.stats(db),attempts=db.attempts.slice().reverse().slice(0,12),evidence=C.evidenceSummary(db),rubric=C.rubricProgress(db);
    return `<div class="pagehead"><div><div class="eyebrow">Learning evidence</div><h1>Progress without guesswork.</h1><p>Review attempts and upcoming work. This prototype shows self-rated attempts and assessment coverage, not calibrated mastery or exam-score predictions.</p></div></div><div class="grid cols3">${metric('Recall targets',s.targets,'Across all requirements')}${metric('Attempted',s.practiced,'Targets with review history')}${metric('Due / new',s.due,'Eligible for practice')}</div><section class="section"><div class="card"><div class="card-title"><h2>What your practice records actually mean</h2><span class="pill blue">Learner self-report</span></div><div class="grid cols3">${metric('Self-rated Good / Easy',evidence.independentSelfReport,'Unassisted by hint; not verified grading')}${metric('With hints',evidence.assisted,'Supported practice, not independent recall')}${metric('Needs practice',evidence.needsPractice,'Includes reported criterion gaps')}</div><p class="info" style="margin-top:15px">Recorded responses: ${evidence.written} written · ${evidence.oral} spoken (self-report) · ${evidence.mental} mentally recalled or unrecorded. These counts are attempts, not unique topics. The app does not assess answer correctness.</p><p class="muted small">Timing samples: ${evidence.withTiming} attempts with plausible active-task durations. Estimated times are personal planning aids, not claims about learning performance.</p></div></section><section class="section"><div class="card"><div class="card-title"><h2>Explanation checklist evidence</h2><span class="pill blue">Self-check · not grading</span></div><div class="grid cols4">${metric('Rubric points',rubric.total,'Active, verified criteria')}${metric('Included',rubric.met,'Latest applicable self-check')}${metric('Missed / unsure',rubric.missed+rubric.unsure,'Self-reported explanation gaps')}${metric('Not yet checked',rubric.unassessed,'Missing criterion-level evidence')}</div>${rubric.pendingReview?`<p class="info warningtext" style="margin-top:12px">${rubric.pendingReview} criterion(s) await review after an edit.</p>`:''}<p class="info" style="margin-top:12px">Each point reflects your latest applicable self-check, not an AI score, evidence of delayed retention, or exam readiness. Revisions preserve older attempts without treating them as current proof.</p></div></section><section class="section grid cols2"><div class="card"><div class="card-title"><h2>Course coverage</h2></div>${db.courses.length?db.courses.map(c=>{const reqs=db.requirements.filter(r=>r.courseId===c.id&&r.active);const targets=reqs.flatMap(r=>C.getTargets(db,r.id,{includePending:true}));const n=targets.filter(t=>!!db.memory[t.id]).length;return `<div style="margin-bottom:17px"><div style="display:flex;justify-content:space-between;margin-bottom:7px"><strong>${esc(c.name)}</strong><span class="small muted">${n}/${targets.length} recall targets attempted</span></div><div class="progress"><span style="width:${targets.length?Math.round(100*n/targets.length):0}%"></span></div></div>`;}).join(''):'<p class="muted">Create courses to see coverage.</p>'}<p class="info">Attempt coverage is not a mastery score.</p></div><div class="card"><div class="card-title"><h2>Recent recall attempts</h2></div>${attempts.length?attempts.map(a=>`<div class="listrow"><span class="roundicon">${courseName(a.courseId)[0]}</span><div class="rowbody"><strong>${esc(a.questionSnapshot||reqById(a.requirementId)?.question||'Historical question')}</strong><small>${esc(courseName(a.courseId))} · ${new Date(a.createdAt).toLocaleDateString()}${a.assisted?' · With hint':''}</small></div><span class="pill ${rClass(a.scheduleRating||a.rating)}">${rateLabel(a.rating)}${a.scheduleRating&&a.scheduleRating!==a.rating?' · gap':''}</span></div>`).join(''):'<p class="muted">No recall attempts yet.</p>'}</div></section><section class="section"><div class="card"><div class="card-title"><h2>Data and privacy controls</h2></div><div class="note" style="margin-bottom:18px"><strong>Local-only storage — no accounts, billing, or server</strong><br>This free app stores your notes on your device using IndexedDB when supported (with a localStorage fallback). GitHub Pages hosts only the public application code; your private notes are not uploaded. Browser cleanup, device changes, and private browsing may remove local data. Export regular JSON backups, and do not enter sensitive personal or student information into this unencrypted prototype. <strong>No automatic cross-device sync.</strong><br><br><strong>Storage status:</strong> <span id="storage-status">${esc(Store.storageMode())}</span></div><div class="btnrow"><button class="btn secondary" data-action="export">↓ Export JSON backup</button><label class="btn secondary" for="import-file" style="cursor:pointer">↑ Import backup</label><input class="sr-only" type="file" id="import-file" accept=".json,application/json"/><button class="btn secondary" data-action="persist-storage">Request more durable storage</button><button class="btn danger" data-action="reset">Clear local data</button></div></div></section>`;
  }
  function outlook(){
    const prefs=db.agendaPreferences||outlookSettings;
    const report=C.buildReviewAgenda(db,{start:new Date(),...prefs});
    const hours=Math.round(report.days.reduce((n,d)=>n+d.budgetMinutes,0)/6)/10;
    const todayKey=C.today();
    const rows=report.days.map(d=>{
      const tasks=d.activities.map(a=>{
        const req=reqById(a.requirementId),target=C.getTargets(db,a.requirementId,{includePending:true}).find(t=>t.id===a.targetId);
        return `<div class="outlook-item ${a.conditional?'conditional-review':''}"><strong>${esc(courseName(a.courseId))}</strong><span>${esc(target?.label||req?.objective||'Recall focus')}</span><small>${Math.ceil(a.seconds/60)} min · ${a.conditional?'Conditional revisit':'Current evidence'} · ${esc(a.reason)}</small></div>`;
      }).join('');
      const used=Math.ceil(d.usedSeconds/60),status=d.overdueUnplaced?` · ${d.overdueUnplaced} pending` :'';
      return `<details class="outlook-day" ${d.date===todayKey?'open':''} ${!d.activities.length?'data-empty="true"':''}><summary><span><strong>${fmtDate(d.date)}</strong> <span class="small muted">${d.budgetMinutes} min available</span></span><span class="small muted">${d.activities.length} opportunities · ${used} min assigned${status}</span></summary>${tasks||`<p class="small muted" style="padding:10px 0">${d.budgetMinutes?'No activity currently fits this day.':'Unavailable day: no activities scheduled.'}</p>`}</details>`;
    }).join('');
    return `<div class="pagehead"><div><div class="eyebrow">Automatic multi-course agenda · local and free</div><h1>Your rolling review calendar.</h1><p>New verified learning, review outcomes and assessment dates are reflected when the calendar is opened or recalculated. The next known review uses current evidence; later repetitions are conditional opportunities, not predictions of your future performance.</p></div></div>
    <section class="section"><div class="card"><div class="card-title"><h2>Your available study time</h2><span class="pill good">Saved locally with your learning data</span></div><form data-form="outlook" class="formgrid">
      <div class="field"><label for="outlook-days">Plan ahead</label><select class="select" name="days" id="outlook-days">${[7,14,21,28,42].map(n=>`<option value="${n}" ${prefs.days===n?'selected':''}>${n} days</option>`).join('')}</select></div>
      <div class="field"><label for="outlook-weekday">Weekdays (minutes per day)</label><input id="outlook-weekday" class="input" type="number" name="weekdayMinutes" min="0" max="720" step="1" required value="${prefs.weekdayMinutes}"/></div>
      <div class="field"><label for="outlook-weekend">Weekends (minutes per day)</label><input id="outlook-weekend" class="input" type="number" name="weekendMinutes" min="0" max="720" step="1" required value="${prefs.weekendMinutes}"/></div>
      <div class="field"><label for="outlook-missed">Unavailable dates</label><input id="outlook-missed" class="input" name="missedDates" maxlength="500" placeholder="2026-11-20, 2026-11-22" value="${esc(prefs.missedDates.join(', '))}"/><small>Comma-separated YYYY-MM-DD dates; the calendar will move tasks to available days.</small></div>
      <div class="wide"><button class="btn primary" type="submit">Save availability and recalculate ↗</button></div>
    </form></div></section>
    <section class="section"><div class="grid cols4">${metric('Available time',hours+' h','Across '+report.days.length+' days')}${metric('Known review slots',report.plannedTargets,'First opportunity for each target')}${metric('Conditional revisits',report.conditionalOpportunities,'Later windows, not assumed results')}${metric('Could not fit',report.unplannedDue,'Known due opportunities inside horizon')}</div></section>
    <section class="section grid cols2 outlook-summary"><div class="card"><div class="card-title"><h2>Upcoming assessment coverage</h2><span class="pill blue">Opportunities, not mastery</span></div>${report.coverage.length?report.coverage.map(c=>`<div class="outlook-exam"><div class="outlook-exam-top"><strong>${esc(c.title)}</strong><span class="small muted">${fmtDate(c.date)}</span></div><p class="small muted">${esc(courseName(c.courseId))} · ${c.firstPass}/${c.eligibleTargets} targets with a known review opportunity before the assessment · ${c.conditionalOpportunities} conditional revisits${c.blocked?` · ${c.blocked} held for verification`:''}.</p><div class="progress"><span style="width:${c.eligibleTargets?Math.round(c.firstPass*100/c.eligibleTargets):0}%"></span></div></div>`).join(''):'<p class="muted small">Add an upcoming assessment to see whether eligible learning targets have a proposed study slot before the deadline.</p>'}<p class="info" style="margin-top:12px">A scheduled opportunity is not a forecast of grades, proof of learning, predicted retention or exam readiness.</p></div>
    <div class="card"><div class="card-title"><h2>What is known versus conditional?</h2></div><p class="small muted"><strong>Known review:</strong> derived from the actual saved due date or a not-yet-attempted target. <strong>Conditional revisit:</strong> a planning placeholder for subsequent spaced practice; its actual date changes when you study, use hints, or miss important explanation criteria.</p><div class="note" style="margin-top:15px"><strong>Research limitation</strong><br>${esc(report.warning)}</div></div></section>
    <section class="section"><div class="card"><div class="card-title"><h2>Day-by-day review agenda</h2><span class="pill">${report.days.length} days</span></div><div class="outlook-days">${rows}</div><p class="small muted" style="margin-top:16px">The plan is recalculated from your current learning records whenever you open it. These are proposed review windows, not background reminders or fixed appointments. A completed session changes future calculations; the current Study Now queue remains available for shorter or longer sessions.</p></div></section>`;
  }
  function render(){let content=page==='home'?dashboard():page==='capture'?capture():page==='study'?session():page==='courses'?courses():page==='assessments'?assessments():page==='forecast'?outlook():insights();$('#app').innerHTML=shell(content);}
  function selectNext(se){
    const remain=Math.max(0,sessionRemainingMs(se)/60000),plan=C.planActivities(db,remain,se.completedIds,se.courseCounts);
    let chosen=plan.items[0]||null;
    if(plan.items.length){
      // Both views use the same target IDs, saved review evidence and availability.
      // A longer Study Now session can still use other eligible work after today's
      // calendar tasks are completed or if none fit the remaining minutes.
      try{
        const prefs=db.agendaPreferences||outlookSettings;
        const today=C.buildReviewAgenda(db,{...prefs,start:new Date()}).days[0]?.activities||[];
        const priorities=new Map(today.filter(task=>!task.conditional).map((task,index)=>[task.targetId,index]));
        const preferred=plan.items.filter(item=>priorities.has(item.target.id));
        if(preferred.length)chosen=preferred.sort((a,b)=>priorities.get(a.target.id)-priorities.get(b.target.id))[0];
      }catch{ /* An unavailable planning preference must not block practice. */ }
    }
    se.currentReqId=chosen?.req.id||null;se.currentActivityId=chosen?.activity?.id||null;se.currentTargetId=chosen?.target?.id||null;se.draftAnswer='';se.showHint=false;se.showReference=false;se.assistedForCurrent=false;se.criterionDraft={};se.activityStartedElapsedMs=sessionElapsedMs(se);
    if(!se.currentReqId)finishSession(se);
  }
  function finishSession(se){if(!se||se.status!=='active')return;if(!se.paused){se.elapsedMs=sessionElapsedMs(se);se.paused=true;se.runningSince=null;}se.status='completed';se.completedAt=new Date().toISOString();se.currentReqId=null;}
  function startSession(){if(!C.eligibleCandidates(db).length)throw Error('Add a learning requirement or verify your generated questions in Knowledge before starting a session.');const now=Date.now();const se={id:C.id('session'),status:'active',budgetMinutes:duration,createdAt:new Date().toISOString(),runningSince:now,elapsedMs:0,paused:false,completedIds:[],courseCounts:{},currentReqId:null,currentActivityId:null,currentTargetId:null,draftAnswer:'',showHint:false,showReference:false,assistedForCurrent:false,criterionDraft:{},activityStartedElapsedMs:0};db.sessions.push(se);currentSessionId=se.id;selectNext(se);page='study';}
  function pauseSession(se){if(se.paused)return;se.elapsedMs=sessionElapsedMs(se);se.paused=true;se.runningSince=null;}
  function resumeSession(se){if(!se.paused)return;se.runningSince=Date.now();se.paused=false;}
  function handleAction(btn){const action=btn.dataset.action;const se=activeSession();switch(action){
    case 'navigate':page=btn.dataset.page;modalReqId=null;studioSourceId=null;render();break;
    case 'navigate-courses':page='courses';render();break;
    case 'navigate-capture':page='capture';render();break;
    case 'discard-document':pendingDocument=null;render();break;
    case 'jump-outline':case 'jump-source-outline':{const field=action==='jump-outline'?$('#import-preview-text'):$('.modal textarea[name=content]');if(field){const offset=Math.max(0,Math.min(field.value.length,Number(btn.dataset.offset)||0));field.focus();field.setSelectionRange(offset,offset);const before=field.value.slice(0,offset);field.scrollTop=Math.max(0,before.split('\n').length-3)*20;}break;}
    case 'duration':duration=Number(btn.dataset.minutes);render();break;
    case 'demo':if(db.courses.length||db.requirements.length){notify('Use Clear local data to start fresh before loading demo content.',true);return;}transact(()=>{db=C.demoDb();focusedCourse=db.courses[0].id;});break;
    case 'focus-course':focusedCourse=btn.dataset.id;render();break;
    case 'edit-requirement':modalReqId=btn.dataset.id;modalSourceId=null;render();break;
    case 'add-focus':modalReqId='focus:'+btn.dataset.id;modalSourceId=null;render();break;
    case 'verify-focus':transact(()=>{C.verifyRetrievalTarget(db,btn.dataset.id);notify('Recall focus verified.');});break;
    case 'add-variation':modalReqId='variant:'+btn.dataset.id+':'+(btn.dataset.targetId||C.getTarget(db,btn.dataset.id).id);modalSourceId=null;render();break;
    case 'manage-rubric':modalReqId='rubric:'+btn.dataset.id+':'+btn.dataset.targetId;modalSourceId=null;render();break;
    case 'suggest-criteria':transact(()=>{const out=C.proposeCriteria(db,{targetId:btn.dataset.targetId});notify(out.length?`${out.length} source-grounded draft point(s) added for verification.`:'No new supported checkpoint suggestions. You can add one manually.');});break;
    case 'verify-criterion':transact(()=>{C.verifyCriterion(db,btn.dataset.id);notify('Checklist point verified.');});break;
    case 'archive-criterion':if(window.confirm('Archive this checklist point? Historical self-checks will remain in backup and practice records.'))transact(()=>C.archiveCriterion(db,btn.dataset.id));break;
    case 'archive-variation':{if(window.confirm('Archive this question variation? Your earlier attempts will be kept.'))transact(()=>C.deactivateActivity(db,btn.dataset.id));break;}
    case 'open-question-studio':studioSourceId=btn.dataset.id;modalReqId=null;modalSourceId=null;render();break;
    case 'adopt-question-proposal':{const ret=transact(()=>C.adoptQuestionProposal(db,{sourceId:btn.dataset.sourceId,key:btn.dataset.key}));if(ret){studioSourceId=null;modalReqId=ret.requirement.id;render();notify(ret.mode==='replaced_unverified_draft'?'Improved the original unverified draft. Review and verify it.':'Saved a new unverified draft. Review the question, answer and source before verifying.');}break;}
    case 'edit-source':modalSourceId=btn.dataset.id;modalReqId=null;render();break;
    case 'verify-requirement':transact(()=>{C.verifyRequirement(db,btn.dataset.id);notify('Requirement verified.');});break;
    case 'add-manual':if(!focusedCourse){notify('Choose a course first.',true);return;}studioSourceId=null;modalReqId='new';render();break;
    case 'close-modal':modalReqId=null;modalSourceId=null;studioSourceId=null;render();break;
    case 'start-session':{const custom=$('#custom-duration');if(custom){const v=Number(custom.value);if(!Number.isInteger(v)||v<5||v>720){notify('Choose a duration between 5 and 720 minutes.',true);return;}duration=v;}
      transact(()=>startSession());break;}
    case 'pause-session':transact(()=>{if(se)pauseSession(se);});break;
    case 'resume-session':transact(()=>{if(se)resumeSession(se);});break;
    case 'extend-session':transact(()=>{if(se&&se.status==='active')se.budgetMinutes+=Number(btn.dataset.minutes);});break;
    case 'remaining-five':transact(()=>{if(se&&se.status==='active')se.budgetMinutes=sessionElapsedMs(se)/60000+5;});break;
    case 'finish-session':transact(()=>{if(se)finishSession(se);});break;
    case 'hint':transact(()=>{if(se&&!se.paused){se.showHint=true;se.assistedForCurrent=true;}});break;
    case 'reveal':transact(()=>{if(se&&!se.paused){const field=$('#study-response');if(field)se.draftAnswer=field.value;se.showReference=true;}});break;
    case 'rate':{if(!se||se.paused||!se.showReference)return;transact(()=>{const rid=se.currentReqId,req=reqById(rid);const rating=btn.dataset.rating;C.recordAttempt(db,{requirementId:rid,activityId:se.currentActivityId,targetId:se.currentTargetId,response:se.draftAnswer,rating,assisted:se.assistedForCurrent,sessionId:se.id,inputMode:$('#response-mode')?.value==='oral'?'oral':$('#response-mode')?.value==='mental'?'mental':null,durationSeconds:Math.max(0,Math.round((sessionElapsedMs(se)-(se.activityStartedElapsedMs??sessionElapsedMs(se)))/1000)),criterionChecks:Object.entries(se.criterionDraft||{}).map(([criterionId,status])=>({criterionId,status}))});se.completedIds.push(se.currentTargetId);se.courseCounts[req.courseId]=(se.courseCounts[req.courseId]||0)+1;selectNext(se);});break;}
    case 'new-session':transact(()=>{currentSessionId=null;page='study';});break;
    case 'delete-assessment':{const id=btn.dataset.id;const a=db.assessments.find(x=>x.id===id);if(a&&window.confirm(`Remove assessment “${a.title}”?`)){transact(()=>{db.assessments=db.assessments.filter(x=>x.id!==id);db.events.push({type:'assessment.deleted',entityId:id,at:new Date().toISOString()});});}break;}
    case 'persist-storage':{Store.requestPersistence().then(ok=>notify(ok?'Browser granted more durable local storage.':'Browser did not grant persistent storage. Export backups regularly.')).catch(()=>notify('Persistent storage is not supported. Export backups regularly.',true));break;}
    case 'export':{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`active-recall-backup-${C.today()}.json`;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup exported.');break;}
    case 'reset':if(window.confirm('Delete all local courses, notes, practice attempts, and assessments in this browser? Export first if you want a backup.'))transact(()=>{db=C.initialDb();currentSessionId=null;focusedCourse=null;page='home';});break;
  }}
  function handleForm(form){const f=new FormData(form),kind=form.dataset.form;
    switch(kind){
      case 'outlook':{try{const days=Number(f.get('days')),weekdayMinutes=Number(f.get('weekdayMinutes')),weekendMinutes=Number(f.get('weekendMinutes'));const missedDates=String(f.get('missedDates')||'').split(/[\s,]+/).filter(Boolean);C.buildReviewAgenda(db,{days,weekdayMinutes,weekendMinutes,missedDates});outlookSettings={days,weekdayMinutes,weekendMinutes,missedDates};transact(()=>{db.agendaPreferences={...outlookSettings};});notify('Availability saved. Future review agenda recalculated.');}catch(error){notify(error.message,true);}break;}
      case 'add-course':transact(()=>{const c=C.addCourse(db,f.get('name'));focusedCourse=c.id;notify('Course created.');});break;
      case 'capture':transact(()=>{const ret=C.addSource(db,{courseId:f.get('courseId'),title:f.get('title'),content:f.get('content')});focusedCourse=ret.source.courseId;page='courses';notify(`Source saved: ${ret.added} draft(s), ${ret.duplicates} repeat(s) linked, ${ret.needsReview} need careful review${ret.conflicts?' and '+ret.conflicts+' possible contradiction(s)':''}.`);});break;
      case 'import-document':{if(!pendingDocument){notify('Choose a document first.',true);break;}if(pendingDocument.format==='pdf'&&f.get('pdfReviewed')!=='yes'){notify('Review the extracted PDF text against the original and confirm before importing.',true);break;}if(pendingDocument.extractionAudit?.missingPages?.length&&f.get('missingPagesAcknowledged')!=='yes'){notify('Acknowledge the PDF pages with missing text before importing.',true);break;}transact(()=>{const ret=C.addImportedDocument(db,{courseId:f.get('courseId'),title:f.get('title'),document:{...pendingDocument,content:f.get('content'),originalExtractedText:pendingDocument.content,reviewed:pendingDocument.format==='pdf'&&f.get('pdfReviewed')==='yes',missingPagesAcknowledged:f.get('missingPagesAcknowledged')==='yes'}});focusedCourse=f.get('courseId');pendingDocument=null;page='courses';notify(`Imported ${ret.parts} source part(s), proposed ${ret.added} draft(s), linked ${ret.duplicates} repeated items. Please verify questions before relying on them.`);});break;}
      case 'add-focus':transact(()=>{C.addRetrievalTarget(db,{requirementId:f.get('requirementId'),label:f.get('label'),question:f.get('question'),answer:f.get('answer'),kind:f.get('kind')});modalReqId=null;notify('Distinct recall focus added with its own review history.');});break;
      case 'add-variation':transact(()=>{C.addActivityVariant(db,{requirementId:f.get('requirementId'),targetId:f.get('targetId'),question:f.get('question'),answer:f.get('answer'),kind:f.get('kind'),objective:f.get('objective')});modalReqId=null;notify('Question variation added to the same learning target.');});break;
      case 'add-criterion':transact(()=>{C.addCriterion(db,{targetId:f.get('targetId'),text:f.get('text')});notify('Explanation point added.');});break;
      case 'revise-criterion':transact(()=>{C.reviseCriterion(db,f.get('id'),f.get('text'));notify('Criterion version saved.');});break;
      case 'save-source':transact(()=>{C.reviseSource(db,f.get('id'),{title:f.get('title'),content:f.get('content')});modalSourceId=null;notify('Source version saved. Review linked requirements before continuing recall.');});break;
      case 'save-requirement':transact(()=>{if(f.get('id'))C.editRequirement(db,f.get('id'),{question:f.get('question'),answer:f.get('answer'),kind:f.get('kind'),objective:f.get('objective'),changeType:f.get('changeType')});else C.addRequirement(db,{courseId:f.get('courseId'),question:f.get('question'),answer:f.get('answer'),kind:f.get('kind'),objective:f.get('objective')});modalReqId=null;notify('Requirement saved.');});break;
      case 'add-assessment':transact(()=>{C.addAssessment(db,{title:f.get('title'),courseId:f.get('courseId'),date:f.get('date'),scope:f.get('scope'),requirementIds:f.getAll('requirementIds')});notify('Assessment added to the planning horizon.');});break;
    }
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;handleAction(b);});
  document.addEventListener('submit',e=>{if(!e.target.matches('form[data-form]'))return;e.preventDefault();handleForm(e.target);});
  document.addEventListener('change',e=>{if(e.target.matches('input[data-criterion-id]')){const se=activeSession();if(se&&se.status==='active'){se.criterionDraft=se.criterionDraft||{};se.criterionDraft[e.target.dataset.criterionId]=e.target.value;save();}}if(e.target.matches('#assessment-scope,#assessment-course'))assessmentSelection();if(e.target.matches('#import-file')){
    const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=C.validateImport(JSON.parse(reader.result));if(!window.confirm('Replace all current local data with the imported backup?'))return;db=data;currentSessionId=null;focusedCourse=null;page='home';save();render();notify('Backup imported.');}catch(err){notify(err.message||'Could not import file.',true);}};reader.readAsText(file);
  }});
  document.addEventListener('change',async e=>{
    if(e.target.id!=='document-file')return;
    const file=e.target.files?.[0];if(!file)return;
    const selectedCourse=$('#capture-course')?.value||focusedCourse;const selectedPdfMode=$('#pdf-mode')?.value||'auto';
    documentImportBusy=true;pendingDocument=null;render();
    try{const result=await Doc.extractFile(file,{pdfMode:selectedPdfMode,confirmOnlineFallback:(reason)=>window.confirm('The offline reader cannot decode this PDF. Load the free PDF.js reader from cdnjs to extract it in your browser? Your PDF file will not be sent to a server.\n\n'+reason)});pendingDocument=result;focusedCourse=selectedCourse;notify(`Extracted ${result.characters.toLocaleString()} characters locally. Check the preview before importing.`);}
    catch(err){pendingDocument=null;notify(err.message||'Could not read the selected document.',true);}
    finally{documentImportBusy=false;render();}
  });
  document.addEventListener('input',e=>{if(e.target.id==='study-response'){const se=activeSession();if(se&&se.status==='active'){se.draftAnswer=e.target.value;save();}}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(modalReqId||modalSourceId)){modalReqId=null;modalSourceId=null;render();}});
  setInterval(()=>{const se=activeSession();if(!se||se.status!=='active'||page!=='study')return;const remaining=sessionRemainingMs(se),timer=$('#study-timer'),p=$('#study-progress');if(timer)timer.textContent=timeStr(remaining);if(p)p.style.width=`${Math.min(100,100*sessionElapsedMs(se)/(se.budgetMinutes*60000))}%`;if(remaining===0){const existing=$('#time-expired');if(!existing&&timer){timer.style.color='#a24a47';timer.title='Time budget reached. Finish this activity or end the session.';}}
  },1000);
  async function boot(){
    try {
      const saved=await Store.load();
      db=saved?.db?C.validateImport(saved.db):C.initialDb();
      const stored=saved?.activeSessionId;
      if(stored&&db.sessions.some(s=>s.id===stored&&s.status==='active')){currentSessionId=stored;page='study';}
      render();
      if(saved?.db && saved.db.schemaVersion!==db.schemaVersion) save();
    } catch(error) {
      // Never overwrite a possibly recoverable local database on load failure.
      $('#app').innerHTML='<main style="padding:32px;font:16px system-ui;max-width:640px"><h1>Could not load your saved learning data</h1><p>Your existing data has not been reset. Do not clear browser data. Try reloading or export your legacy backup from the previous version before continuing.</p><pre style="white-space:pre-wrap" id="boot-error"></pre></main>';
      $('#boot-error').textContent=error.message||String(error);
    }
  }
  boot();
})();
